import './App.css';
import React, { useEffect, useMemo, useState } from 'react'; 
import { BrowserRouter as Router, Routes, Route, Link, NavLink } from 'react-router-dom';
import { modulesConfig } from './config/modulesConfig';
import Login from './componentes/Login';
import Swal from 'sweetalert2';

const normalizeText = (value = '') => value
  .toString()
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .trim();

const MODULE_PERMISSION_ALIASES = {
  menu_general: ['menu principal', 'menu general'],
  anulacion_deuda: ['anular cobro', 'anulacion deuda', 'anulacion de deuda'],
  convenio: ['convenio', 'convenio pagos', 'convenio de pagos'],
  caja_ingresos: ['caja ingresos manual'],
  asignar_correlativo: ['asignar correlativos', 'asignar correlativo', 'cuadre del dia', 'cuadre del mes'],
  proyectos: ['proyecto', 'proyectos', 'catalogo de proyectos', 'catalogo proyectos'],
  empresa_proyecto: ['empresa proyecto', 'empresa-proyecto', 'proyecto empresa'],
  dashboard_financiero: ['dashboard', 'dashboard financiero', 'reportes', 'reporte financiero', 'estadisticas', 'reportes financieros']
};

const getFallbackPermisosByRole = (rolNormalizado = '') => {
  if (rolNormalizado.includes('jurid') || rolNormalizado.includes('legal')) {
    return new Set([
      normalizeText('Caja (General)'),
      normalizeText('Mora y Atrasos'),
      normalizeText('Anular Cobro')
    ]);
  }

  if (rolNormalizado.includes('cobro') || rolNormalizado.includes('caja')) {
    return new Set([
      normalizeText('Caja (General)'),
      normalizeText('Caja Ingresos Manual'),
      normalizeText('Mora y Atrasos'),
      normalizeText('Anular Cobro'),
      normalizeText('Convenio de Pagos'),
      normalizeText('Tabla de Amortización'),
      normalizeText('Pagos'),
      normalizeText('Detalle Pagos'),
      normalizeText('Dashboard Financiero'),
      normalizeText('Reportes'),
      normalizeText('Reporte de Facturas')
    ]);
  }

  return new Set();
};

const parsePermisos = (permisos) => {
  if (Array.isArray(permisos)) {
    return permisos;
  }

  if (typeof permisos === 'string' && permisos.trim()) {
    try {
      const parsed = JSON.parse(permisos);
      return Array.isArray(parsed) ? parsed : [];
    } catch {
      return [];
    }
  }

  return [];
};

const extraerPermisoTokens = (item) => {
  if (!item) {
    return [];
  }

  if (typeof item === 'string' || typeof item === 'number') {
    return [normalizeText(item)];
  }

  if (typeof item === 'object') {
    return [
      item.id,
      item.nombre,
      item.label,
      item.modulo,
      item.path
    ]
      .filter((value) => value !== null && typeof value !== 'undefined' && String(value).trim())
      .map((value) => normalizeText(String(value).replace(/^\//, '')));
  }

  return [];
};

const detectarPerfilCaja = (rolNormalizado, permisosNormalizados) => {
  if (rolNormalizado.includes('cobro') || rolNormalizado.includes('caja')) {
    return true;
  }

  const pistasCaja = ['caja', 'cobro', 'morosidad', 'pagos', 'convenio'];
  for (const permiso of permisosNormalizados) {
    if (pistasCaja.some((pista) => permiso.includes(pista))) {
      return true;
    }
  }

  return false;
};

const showFadeToast = (message, icon = 'info') => {
  Swal.fire({
    toast: true,
    position: 'top-end',
    icon,
    title: message,
    showConfirmButton: false,
    timer: 2600,
    timerProgressBar: true,
    showClass: {
      popup: 'swal-toast-fade-in'
    },
    hideClass: {
      popup: 'swal-toast-fade-out'
    }
  });
};

const installToastAlertOverride = () => {
  if (typeof window === 'undefined' || window.__toastAlertInstalled) {
    return;
  }

  const nativeAlert = window.alert.bind(window);

  window.__nativeAlert = nativeAlert;
  window.alert = (message) => {
    showFadeToast(String(message || 'Notificacion del sistema'), 'error');
  };
  window.__toastAlertInstalled = true;
};

installToastAlertOverride();

function App() {
  const [isMenuOpen, setIsMenuOpen] = useState(true);
  const [isMobileViewport, setIsMobileViewport] = useState(() => window.innerWidth <= 992);
  const [expandedCategories, setExpandedCategories] = useState({});
  const logoSources = ['/images/logo.svg'];
  const [logoIndex, setLogoIndex] = useState(0);
  const [usuarioActivo, setUsuarioActivo] = useState({});
  const [isAuthenticated, setIsAuthenticated] = useState(false);

  useEffect(() => {
    const handleResize = () => {
      const mobile = window.innerWidth <= 992;
      setIsMobileViewport(mobile);
      setIsMenuOpen((prev) => (mobile ? false : prev || true));
    };

    handleResize();
    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('resize', handleResize);
    };
  }, []);

  useEffect(() => {
    const originalFire = Swal.fire.bind(Swal);

    const normalizeFireArgs = (args) => {
      const [arg1, arg2, arg3] = args;

      if (arg1 && typeof arg1 === 'object' && !Array.isArray(arg1)) {
        return { ...arg1 };
      }

      if (typeof arg1 !== 'undefined') {
        return {
          title: String(arg1 || ''),
          text: typeof arg2 === 'undefined' ? undefined : String(arg2),
          icon: typeof arg3 === 'undefined' ? undefined : arg3
        };
      }

      return null;
    };

    const shouldKeepAsModal = (opts = {}) => {
      if (opts.toast === true) return false;
      if (opts.showCancelButton) return true;
      if (opts.input) return true;
      if (typeof opts.preConfirm === 'function') return true;
      if (typeof opts.willOpen === 'function' || typeof opts.didOpen === 'function') return true;
      return false;
    };

    Swal.fire = (...args) => {
      const options = normalizeFireArgs(args);
      if (!options) {
        return originalFire(...args);
      }

      if (shouldKeepAsModal(options)) {
        return originalFire(...args);
      }

      const toastConfig = {
        ...options,
        toast: true,
        position: options.position || 'top-end',
        showConfirmButton: false,
        timer: options.timer || 2600,
        timerProgressBar: true,
        showClass: options.showClass || { popup: 'swal-toast-fade-in' },
        hideClass: options.hideClass || { popup: 'swal-toast-fade-out' }
      };

      return originalFire(toastConfig);
    };

    return () => {
      Swal.fire = originalFire;
    };
  }, []);

  useEffect(() => {
    const cargarUsuarioActivo = () => {
      try {
        const data = JSON.parse(localStorage.getItem('usuario') || '{}');
        setUsuarioActivo(data || {});
        setIsAuthenticated(Boolean(data && data.id_usuario));
      } catch {
        setUsuarioActivo({});
        setIsAuthenticated(false);
      }
    };

    cargarUsuarioActivo();
    window.addEventListener('focus', cargarUsuarioActivo);
    window.addEventListener('storage', cargarUsuarioActivo);
    window.addEventListener('usuario-updated', cargarUsuarioActivo);

    return () => {
      window.removeEventListener('focus', cargarUsuarioActivo);
      window.removeEventListener('storage', cargarUsuarioActivo);
      window.removeEventListener('usuario-updated', cargarUsuarioActivo);
    };
  }, []);

  const inicialesUsuario = useMemo(() => {
    const nombre = String(usuarioActivo.nombre_usuario || usuarioActivo.nombre || 'USUARIO').trim();
    const partes = nombre.split(' ').filter(Boolean);
    if (!partes.length) return 'U';
    return (partes[0][0] + (partes[1]?.[0] || '')).toUpperCase();
  }, [usuarioActivo]);

  const toggleMenu = () => {
    setIsMenuOpen(!isMenuOpen);
  };

  const handleMobileModuleNavigation = () => {
    if (window.innerWidth <= 992) {
      setIsMenuOpen(false);
    }
  };

  const cerrarSesionTemporal = () => {
    localStorage.removeItem('usuario');
    setUsuarioActivo({});
    setIsAuthenticated(false);

    window.dispatchEvent(new Event('usuario-updated'));
  };

  const onLoginSuccess = (usuario) => {
    setUsuarioActivo(usuario || {});
    setIsAuthenticated(Boolean(usuario && usuario.id_usuario));
  };

  const modulesPermitidos = useMemo(() => {
    if (!isAuthenticated) {
      return [];
    }

    const permisos = parsePermisos(usuarioActivo.permisos);
    const permisosNormalizados = new Set(
      permisos.flatMap((item) => extraerPermisoTokens(item)).filter(Boolean)
    );
    const rolNormalizado = normalizeText(usuarioActivo.nombre_rol);
    const esAdmin = rolNormalizado.includes('admin') || rolNormalizado.includes('administrador') || rolNormalizado.includes('superusuario');
    const fallbackPermisos = getFallbackPermisosByRole(rolNormalizado);
    const rolTieneAccesoCaja = rolNormalizado.includes('jurid')
      || rolNormalizado.includes('legal')
      || (rolNormalizado.includes('gestor') && rolNormalizado.includes('cobro'));
    const perfilCaja = permisosNormalizados.size === 0
      && detectarPerfilCaja(rolNormalizado, permisosNormalizados);
    const permisosEfectivos = new Set([
      ...permisosNormalizados,
      ...((perfilCaja || rolTieneAccesoCaja) ? Array.from(fallbackPermisos) : [])
    ]);

    return modulesConfig.filter((module) => {
      if (esAdmin) {
        return true;
      }

      if (module.id === 'asignar_correlativo') {
        return false;
      }

      if (module.id === 'menu_general') {
        return true;
      }

      if (permisosEfectivos.size === 0) {
        return false;
      }

      const candidates = [
        module.id,
        module.label,
        module.path.replace('/', ''),
        ...(MODULE_PERMISSION_ALIASES[module.id] || [])
      ].map(normalizeText);

      return candidates.some((candidate) => permisosEfectivos.has(candidate));
    });
  }, [isAuthenticated, usuarioActivo]);

  const categories = useMemo(() => {
    return [...new Set(modulesPermitidos.map((module) => module.category))];
  }, [modulesPermitidos]);

  // Toggle para expandir/contraer categorías
  const toggleCategory = (category) => {
    setExpandedCategories(prev => ({
      ...prev,
      [category]: !prev[category]
    }));
  };

  // Inicializar todas las categorías como expandidas
  const initializeCategories = () => {
    const initialized = {};
    categories.forEach(cat => {
      if (expandedCategories[cat] === undefined) {
        initialized[cat] = true;
      }
    });
    return initialized;
  };

  const finalExpandedState = { ...initializeCategories(), ...expandedCategories };

  if (!isAuthenticated) {
    return (
      <Router>
        <Login onLoginSuccess={onLoginSuccess} />
      </Router>
    );
  }

  return (
    <Router>
      <div className="container-fluid"> 
        <div className="row app-shell-row">
          
          {/* BARRA LATERAL DINÁMICA (SIDEBAR) */}
          <div 
            className={`bg-light p-3 shadow-sm min-vh-100 transition-all sidebar-shell app-sidebar ${
              isMenuOpen ? 'col-md-3 col-lg-2 is-open' : 'col-auto d-flex flex-column align-items-center is-collapsed'
            }`}
            style={{ transition: 'all 0.3s' }}
          >
            {/* LOGO */}
            <div className="mb-4 w-100 d-flex justify-content-center">
              <Link to="/menu_general" title="Ir al menu general" className="d-inline-block text-center text-decoration-none" style={{ minHeight: '76px' }}>
                {logoIndex < logoSources.length ? (
                  <img 
                    src={logoSources[logoIndex]}
                    alt="Grupo de Inversiones" 
                    onError={() => setLogoIndex((prev) => prev + 1)}
                    style={{
                      maxWidth: isMenuOpen ? '150px' : '42px',
                      height: 'auto',
                      maxHeight: '72px',
                      transition: 'all 0.3s',
                      cursor: 'pointer'
                    }} 
                  />
                ) : (
                  <div className="fw-bold text-primary" style={{ fontSize: isMenuOpen ? '0.95rem' : '0.75rem' }}>
                    GRUPO DE INVERSION
                  </div>
                )}
                {isMenuOpen && (
                  <div className="small text-success fw-bold mt-1" style={{ letterSpacing: '0.3px' }}>
                    GRUPO DE INVERSION
                  </div>
                )}
              </Link>
            </div>

            <button className="btn btn-primary mb-4 w-100" onClick={toggleMenu}>
              {isMobileViewport ? (isMenuOpen ? 'Ocultar menu' : 'Mostrar menu') : (isMenuOpen ? '◀ Contraer' : '▶')}
            </button>

            {isMenuOpen && <h5 className="fw-bold mb-4 text-center text-secondary">⚙️ Sistema</h5>}

            {/* MENÚ DINÁMICO POR CATEGORÍAS */}
            <nav className="nav flex-column w-100 gap-2">
              {categories.map((category, idx) => (
                <div key={idx} className="mb-3">
                  {isMenuOpen && (
                    <button
                      onClick={() => toggleCategory(category)}
                      className="btn btn-sm btn-link fw-bold d-block mb-2 ps-2 text-start w-100 text-decoration-none sidebar-category-btn"
                      style={{ cursor: 'pointer' }}
                    >
                      <span className="me-2">
                        {finalExpandedState[category] ? '▼' : '▶'}
                      </span>
                      {category}
                    </button>
                  )}
                  
                  {/* Módulos de esta categoría - Mostrar/Ocultar según estado */}
                  {finalExpandedState[category] && (
                    <>
                      {modulesConfig
                        .filter(module => modulesPermitidos.some((permitido) => permitido.id === module.id))
                        .filter(module => module.category === category)
                        .map((module) => (
                          <NavLink
                            key={module.id}
                            to={module.path} 
                            onClick={handleMobileModuleNavigation}
                            className={({ isActive }) => `nav-link fw-bold p-2 text-start d-flex align-items-center sidebar-menu-link ${isActive ? 'is-active' : ''}`}
                          >
                            <span>{module.icon}</span> 
                            {isMenuOpen && <span className="ms-2">{module.label}</span>}
                          </NavLink>
                        ))}
                    </>
                  )}
                </div>
              ))}
            </nav>
          </div>

          {/* CONTENIDO PRINCIPAL (DERECHA) */}
          <div className={`p-4 app-content-with-profile app-main-content ${isMenuOpen ? 'col-md-9 col-lg-10' : 'col'}`}>
            <div className="app-mobile-topbar">
              <button type="button" className="btn btn-outline-primary app-mobile-menu-btn" onClick={toggleMenu}>
                {isMenuOpen ? 'Cerrar menu' : 'Abrir menu'}
              </button>
            </div>
            <div className="perfil-activo-top-right">
              <div className="perfil-activo-card">
                <div className="perfil-activo-header">
                  {usuarioActivo.foto_perfil ? (
                    <img src={usuarioActivo.foto_perfil} alt="Perfil activo" className="perfil-activo-avatar" />
                  ) : (
                    <div className="perfil-activo-iniciales">{inicialesUsuario}</div>
                  )}
                  <div className="perfil-activo-info">
                    <div className="perfil-activo-titulo">Usuario activo</div>
                    <div className="perfil-activo-nombre">{usuarioActivo.nombre_usuario || usuarioActivo.nombre || 'Invitado'}</div>
                    <div className="perfil-activo-rol">{usuarioActivo.nombre_rol || 'Sin rol'}</div>
                  </div>
                </div>
                <button type="button" className="btn btn-sm btn-outline-danger perfil-cerrar-sesion" onClick={cerrarSesionTemporal}>
                  Cerrar sesión
                </button>
              </div>
            </div>
            <Routes>
              {/* RUTAS DINÁMICAS - Se generan automáticamente */}
              {modulesPermitidos.map((module) => {
                const Component = module.component;
                return (
                  <Route 
                    key={module.id}
                    path={module.path} 
                    element={<Component />} 
                  />
                );
              })}
              
              {/* Ruta por defecto */}
              {modulesPermitidos.length > 0 && (() => {
                const DefaultComponent = modulesPermitidos[0].component;
                return <Route path="/" element={<DefaultComponent />} />;
              })()}
              {modulesPermitidos.length === 0 && (
                <Route path="*" element={<div className="alert alert-warning">No tienes módulos asignados. Contacta al administrador.</div>} />
              )}
            </Routes>
          </div>

        </div>
      </div>
    </Router>
  );
}

export default App;