import autoTable from 'jspdf-autotable';

// Formato unico de documento para todo el sistema: RECIBO DE CAJA O COMPROBANTE DE PAGO.
// Lo usan Caja (emision), Detalle de Pagos (reimpresion) y Anulacion de Deuda (anulada),
// para que la factura emitida y la anulada se vean identicas salvo el sello ANULADA.

export const COLOR_ORO = [173, 136, 38];

let contadorImagen = 0;

export const getImageFormatFromDataUrl = (dataUrl = '') => {
  const match = String(dataUrl || '').match(/^data:image\/([a-zA-Z0-9+.-]+);base64,/i);
  if (!match) return 'PNG';
  const rawFormat = match[1].toLowerCase();
  if (rawFormat === 'jpg' || rawFormat === 'jpeg') return 'JPEG';
  if (rawFormat === 'webp') return 'WEBP';
  return 'PNG';
};

export const normalizeImageDataUrl = (value = '') => {
  const raw = String(value || '').trim();
  if (!raw) return '';
  if (raw.startsWith('data:image')) return raw;

  const base64Part = raw.includes('base64,') ? raw.split('base64,')[1] : raw;
  const cleaned = String(base64Part || '').replace(/\s+/g, '');
  if (!cleaned || !/^[A-Za-z0-9+/=]+$/.test(cleaned)) return '';

  let mime = 'image/png';
  if (cleaned.startsWith('/9j/')) {
    mime = 'image/jpeg';
  } else if (cleaned.startsWith('UklGR')) {
    mime = 'image/webp';
  } else if (cleaned.startsWith('iVBOR')) {
    mime = 'image/png';
  }

  return `data:${mime};base64,${cleaned}`;
};

// Construye la leyenda de mora exonerada para el recibo (emitido y anulado).
// Acepta arreglo de strings (formato legado) u objetos { mes_atrasado }.
export const formatearNotaMoraExonerada = (lista = []) => {
  const meses = (Array.isArray(lista) ? lista : [])
    .map((item) => String(typeof item === 'string' ? item : (item?.mes_atrasado || '')).trim())
    .filter(Boolean);

  if (!meses.length) return '';
  if (meses.length === 1) return `Mora exonerada: mes de ${meses[0]}.`;
  return `Mora exonerada: mes de ${meses[0]} a mes de ${meses[meses.length - 1]}.`;
};


const fechaFmt = (d) => `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')}/${d.getFullYear()}`;

const fechaHoraFmt = (d) => {
  const n = new Date();
  return `${fechaFmt(d)}, ${String(n.getHours()).padStart(2, '0')}:${String(n.getMinutes()).padStart(2, '0')}:${String(n.getSeconds()).padStart(2, '0')}`;
};

const texto = (valor, alterno = 'N/A') => {
  const limpio = String(valor ?? '').trim();
  return limpio || alterno;
};

const normalizarConcepto = (valor = '') => String(valor || '')
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .trim();

const inferirTipoConcepto = (detalle = {}) => {
  const tipoDirecto = normalizarConcepto(detalle?.tipo_concepto || '');
  if (tipoDirecto) return tipoDirecto;

  const concepto = normalizarConcepto(detalle?.nombre_concepto || detalle?.concepto || '');
  if (concepto.includes('enganche')) return 'enganche';
  if (concepto.includes('abono a capital')) return 'abono_capital';
  if (concepto.includes('interes')) return 'interes';
  if (concepto.includes('mora')) return 'mora';
  if (concepto.includes('extraordinario')) return 'extraordinario';
  if (concepto.includes('servicio')) return 'servicio';
  if (concepto.includes('cuota')) return 'cuota_terreno';
  return 'otro';
};

const normalizarMesClave = (valor = '') => String(valor || '')
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/\s+/g, ' ')
  .trim();

const obtenerClaveMesBase = (valor = '') => normalizarMesClave(String(valor || '').split(' ')[0] || '');

export const buildConsolidatedInvoiceRows = (detalles = [], options = {}) => {
  const numeroCuotaInicio = Math.max(Number(options?.numeroCuotaInicio || 0), 0);
  const normalizados = (Array.isArray(detalles) ? detalles : [])
    .map((item, index) => {
      const tipoOriginal = inferirTipoConcepto(item);
      const nombreBase = texto(item?.nombre_concepto || item?.concepto || item?.tipo_concepto || 'Pago aplicado');
      const mesBase = texto(item?.mes_pagado || item?.mes, '');
      const cuotaBase = Number(item?.numero_cuota_afectada || item?.numero_cuota || 0) || null;
      // Solo es enganche cuando el concepto lo dice. Antes bastaba con que la cuota no
      // trajera número para marcarla como enganche, y toda cuota financiada del recibo
      // salía rotulada "Cuota 0 Enganche" (con el interés en una fila suelta aparte).
      const esEnganche = tipoOriginal === 'enganche'
        || (tipoOriginal === 'cuota_terreno' && normalizarConcepto(nombreBase).includes('enganche'));

      return {
        orden: index,
        tipo: esEnganche ? 'enganche' : tipoOriginal,
        conceptoOriginal: esEnganche ? 'Enganche / Cuota 0' : nombreBase,
        mes: esEnganche ? 'Enganche / Cuota 0' : mesBase,
        cuotaReal: esEnganche ? 0 : cuotaBase,
        monto: Number(item?.subtotal ?? item?.total ?? 0)
      };
    })
    .filter((item) => Number.isFinite(item.monto) && item.monto > 0);

  if (!normalizados.length) {
    return [['Pago aplicado', 'N/A', 'Q 0.00']];
  }

  const filas = [];
  const filasPorClave = new Map();
  let cuotasSinNumero = 0;

  const obtenerEtiquetaCuota = (cuotaReal, esEnganche = false) => {
    if (esEnganche) return 'Enganche / Cuota 0';

    // El número de cuota guardado ya es el de la cuota financiada real (cuota 1 = primer
    // mes de pagos pactado), así que se imprime tal cual: sin corrimientos por enganche.
    let cuotaVisual = Number(cuotaReal || 0);
    if (!Number.isInteger(cuotaVisual) || cuotaVisual <= 0) {
      cuotaVisual = numeroCuotaInicio > 0 ? numeroCuotaInicio + cuotasSinNumero : 0;
      cuotasSinNumero += 1;
      return cuotaVisual > 0 ? `Cuota ${cuotaVisual}` : 'Cuota';
    }

    return `Cuota ${cuotaVisual}`;
  };

  const asegurarFila = (clave, base = {}) => {
    if (!filasPorClave.has(clave)) {
      const fila = {
        clave,
        orden: base.orden ?? filas.length,
        concepto: base.concepto || 'Pago aplicado',
        mes: base.mes || 'N/A',
        cuota: 0,
        interes: 0,
        mora: 0,
        total: 0,
        cuotaNumero: Number(base.cuotaNumero ?? 0) || null
      };
      filasPorClave.set(clave, fila);
      filas.push(fila);
    }

    return filasPorClave.get(clave);
  };

  const obtenerClaveCuotaAdjunta = (item) => {
    const mesNormalizado = normalizarMesClave(item?.mes || '');
    const cuotaNumero = Number(item?.cuotaReal || 0);

    for (const [clave, fila] of filasPorClave.entries()) {
      if (!String(clave).startsWith('cuota:')) continue;
      const mismoMes = normalizarMesClave(String(fila?.mes || '')) === mesNormalizado;
      const mismaCuota = Number(fila?.cuotaNumero ?? 0) > 0 && cuotaNumero > 0 && Number(fila.cuotaNumero) === cuotaNumero;
      if (mismoMes && (mismaCuota || cuotaNumero <= 0)) {
        return clave;
      }
    }

    const primeraCuota = [...filasPorClave.keys()].find((clave) => clave.startsWith('cuota:'));
    return primeraCuota || null;
  };

  normalizados.forEach((item) => {
    if (item.tipo === 'enganche') {
      const fila = asegurarFila(`enganche:${item.mes || item.orden}`, {
        orden: item.orden,
        concepto: obtenerEtiquetaCuota(0, true),
        mes: 'Enganche / Cuota 0',
        cuotaNumero: 0
      });
      fila.total = Number((fila.total + item.monto).toFixed(2));
      return;
    }

    if (item.tipo === 'cuota_terreno') {
      const clave = `cuota:${item.mes || item.orden}:${item.cuotaReal || 'sin-cuota'}`;
      const fila = asegurarFila(clave, {
        orden: item.orden,
        concepto: obtenerEtiquetaCuota(item.cuotaReal, false),
        mes: item.mes || 'N/A',
        cuotaNumero: item.cuotaReal
      });
      fila.cuota = Number((fila.cuota + item.monto).toFixed(2));
      fila.total = Number((fila.total + item.monto).toFixed(2));
      return;
    }

    if (item.tipo === 'interes') {
      const claveDestino = obtenerClaveCuotaAdjunta(item);
      if (claveDestino && filasPorClave.has(claveDestino)) {
        const fila = filasPorClave.get(claveDestino);
        fila.interes = Number((fila.interes + item.monto).toFixed(2));
        fila.total = Number((fila.total + item.monto).toFixed(2));
        return;
      }
    }

    if (item.tipo === 'mora') {
      const claveMora = `mora:${item.mes || item.orden}`;
      const fila = asegurarFila(claveMora, {
        orden: item.orden,
        concepto: 'Mora',
        mes: item.mes || 'N/A'
      });
      fila.mora = Number((fila.mora + item.monto).toFixed(2));
      fila.total = Number((fila.total + item.monto).toFixed(2));
      return;
    }

    if (item.tipo === 'servicio') {
      const nombreServicio = normalizarConcepto(item.conceptoOriginal).startsWith('servicio')
        ? item.conceptoOriginal
        : `Servicio: ${item.conceptoOriginal}`;
      const fila = asegurarFila(`servicio:${item.mes || 'sin-mes'}:${item.conceptoOriginal}:${item.orden}`, {
        orden: item.orden,
        concepto: nombreServicio,
        mes: item.mes || 'N/A'
      });
      fila.total = Number((fila.total + item.monto).toFixed(2));
      return;
    }

    const clave = `${item.tipo}:${item.mes || 'sin-mes'}:${item.conceptoOriginal}:${item.orden}`;
    const fila = asegurarFila(clave, {
      orden: item.orden,
      concepto: item.conceptoOriginal.replace(/_/g, ' '),
      mes: item.mes || 'N/A'
    });
    fila.total = Number((fila.total + item.monto).toFixed(2));
  });

  return filas
    .filter((fila) => fila.total > 0)
    .sort((a, b) => a.orden - b.orden)
    .map((fila) => {
      const concepto = fila.clave.startsWith('cuota:')
        ? `${fila.concepto} ${texto(fila.mes, '')}`.trim()
        : fila.concepto;
      return [concepto, texto(fila.mes), `Q ${fila.total.toFixed(2)}`];
    });
};

/**
 * Dibuja el formato RECIBO DE CAJA O COMPROBANTE DE PAGO sobre un documento jsPDF ya creado.
 * No guarda el archivo: el llamador decide el nombre con doc.save().
 */
export const renderFacturaComprobante = (doc, datos = {}) => {
  const {
    titulo = ['RECIBO DE CAJA O', 'COMPROBANTE DE PAGO'],
    logo = '',
    empresa = {},
    documentoNo = 'N/A',
    fechaEmision = null,
    cliente = {},
    contrato = 'N/A',
    pago = {},
    rolUsuarioCobro = '',
    encabezados = ['Concepto / Cuota', 'Mes Afectado', 'Total'],
    filas = [],
    resumen = [],
    anulada = false,
    notaPie = 'Gracias por su pago. Conservar este documento para cualquier aclaración fiscal y administrativa.'
  } = datos;

  const pW = doc.internal.pageSize.getWidth();
  const pH = doc.internal.pageSize.getHeight();
  const fecha = fechaEmision instanceof Date && !Number.isNaN(fechaEmision.getTime())
    ? fechaEmision
    : new Date();
  const metodo = String(pago?.metodo || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase();

  let y = 12;
  doc.setFillColor(...COLOR_ORO);
  doc.rect(0, 0, pW, 5, 'F');

  if (logo) {
    try {
      contadorImagen += 1;
      doc.addImage(logo, getImageFormatFromDataUrl(logo), 9, y - 1, 33, 33, `fac-logo-${contadorImagen}`, 'FAST');
    } catch {
      // no-op
    }
  }

  doc.setTextColor(40, 40, 40);
  doc.setFont('Helvetica', 'bold');
  doc.setFontSize(11);
  doc.text(String(empresa?.nombre || 'CORPORACION DE INVERSION INMOBILIARIA').toUpperCase(), 46, y + 5);
  doc.setFont('Helvetica', 'normal');
  doc.setFontSize(8.5);
  doc.text(`NIT: ${texto(empresa?.nit)}`, 46, y + 10);
  doc.text(`País: ${texto(empresa?.pais, 'Guatemala')}`, 46, y + 14.5);
  doc.text(`Moneda: ${texto(empresa?.moneda, 'GTQ')}`, 46, y + 19);

  doc.setFillColor(245, 245, 245);
  doc.rect(140, y - 2, 63, 30, 'F');
  doc.setDrawColor(180, 180, 180);
  doc.rect(140, y - 2, 63, 30);
  doc.setFont('Helvetica', 'bold');
  doc.setFontSize(10);
  doc.text(String(titulo[0] || ''), 171.5, y + 4, { align: 'center' });
  doc.text(String(titulo[1] || ''), 171.5, y + 9, { align: 'center' });
  doc.setFont('Helvetica', 'normal');
  doc.setFontSize(8.2);
  doc.text(`Documento No: ${texto(documentoNo)}`, 171.5, y + 15, { align: 'center' });
  doc.text(`Fecha emisión: ${fechaFmt(fecha)}`, 171.5, y + 20, { align: 'center' });
  doc.text(`Fecha/Hora impresión: ${fechaHoraFmt(fecha)}`, 171.5, y + 25, { align: 'center' });

  y += 36;
  doc.setDrawColor(180, 180, 180);
  doc.setLineWidth(0.3);
  doc.line(10, y, pW - 10, y);
  y += 5;

  // Datos del cliente
  doc.setFillColor(240, 240, 240);
  doc.rect(10, y, pW - 20, 7, 'F');
  doc.setFont('Helvetica', 'bold');
  doc.setFontSize(9.5);
  doc.text('DATOS DEL CLIENTE', 12, y + 5);
  y += 10;

  doc.setFont('Helvetica', 'bold');
  doc.setFontSize(8.5);
  doc.text('Nombre:', 12, y);
  doc.setFont('Helvetica', 'normal');
  doc.text(texto(cliente?.nombre), 35, y);
  doc.setFont('Helvetica', 'bold');
  doc.text('Dirección:', 120, y);
  doc.setFont('Helvetica', 'normal');
  doc.text(texto(cliente?.direccion).slice(0, 38), 143, y);
  y += 6;

  doc.setFont('Helvetica', 'bold');
  doc.text('Identificación:', 12, y);
  doc.setFont('Helvetica', 'normal');
  doc.text(texto(cliente?.identificacion), 42, y);
  doc.setFont('Helvetica', 'bold');
  doc.text('Contrato:', 120, y);
  doc.setFont('Helvetica', 'normal');
  doc.text(texto(contrato), 143, y);
  y += 6;

  doc.setFont('Helvetica', 'bold');
  doc.text('DPI:', 12, y);
  doc.setFont('Helvetica', 'normal');
  doc.text(texto(cliente?.dpi), 24, y);
  doc.setFont('Helvetica', 'bold');
  doc.text('NIT:', 120, y);
  doc.setFont('Helvetica', 'normal');
  doc.text(texto(cliente?.nit, 'CF'), 131, y);
  y += 8;

  // Datos de pago
  doc.setFillColor(240, 240, 240);
  doc.rect(10, y, pW - 20, 7, 'F');
  doc.setFont('Helvetica', 'bold');
  doc.setFontSize(9.5);
  doc.text('DATOS DE PAGO', 12, y + 5);
  y += 10;

  doc.setFont('Helvetica', 'bold');
  doc.setFontSize(8.5);
  doc.text('Método de pago:', 12, y);
  doc.setFont('Helvetica', 'normal');
  doc.text(texto(pago?.metodo), 48, y);
  doc.setFont('Helvetica', 'bold');
  doc.text('Referencia:', 120, y);
  doc.setFont('Helvetica', 'normal');
  const esPagoBancario = metodo.includes('deposit') || metodo.includes('transfer');
  const referenciaPrincipal = esPagoBancario
    ? texto(pago?.boletaReferencia || pago?.referencia || documentoNo)
    : texto(pago?.referencia || documentoNo);
  doc.text(referenciaPrincipal, 143, y);
  y += 10;

  if (rolUsuarioCobro) {
    doc.setFont('Helvetica', 'bold');
    doc.text('Rol que cobra:', 12, y);
    doc.setFont('Helvetica', 'normal');
    doc.text(texto(rolUsuarioCobro), 42, y);
    y += 8;
  }

  const banco = texto(pago?.banco, '');
  const fechaOperacion = texto(pago?.fechaOperacion, '');
  const boletaReferencia = texto(pago?.boletaReferencia, '');
  if (esPagoBancario) {
    doc.setFont('Helvetica', 'bold');
    doc.text('Banco:', 12, y);
    doc.setFont('Helvetica', 'normal');
    doc.text(banco, 28, y);
    doc.setFont('Helvetica', 'bold');
    doc.text('Fecha op.:', 120, y);
    doc.setFont('Helvetica', 'normal');
    doc.text(fechaOperacion, 145, y);
    y += 6;
    doc.setFont('Helvetica', 'bold');
    doc.text('Boleta/Ref.:', 12, y);
    doc.setFont('Helvetica', 'normal');
    doc.text(boletaReferencia, 35, y);
    y += 8;
  }

  // Tabla de detalle
  autoTable(doc, {
    startY: y,
    head: [encabezados],
    body: filas.length ? filas : [['Sin detalle registrado', 'N/A', 'Q 0.00']],
    theme: 'grid',
    styles: { fontSize: 8.5, cellPadding: 2 },
    headStyles: { fillColor: COLOR_ORO, textColor: [255, 255, 255], fontStyle: 'bold', halign: 'center' },
    columnStyles: {
      0: { cellWidth: 95 },
      1: { cellWidth: 50, halign: 'center' },
      2: { cellWidth: 40, halign: 'right' }
    },
    margin: { left: 10, right: 10 }
  });

  y = doc.lastAutoTable.finalY + 8;

  // Resumen
  const resX = pW - 90;
  const resW = 80;
  const lineH = 7;

  doc.setDrawColor(200, 200, 200);
  doc.setLineWidth(0.2);
  doc.line(resX - 2, y - 3, resX + resW + 2, y - 3);

  resumen.forEach(({ label, valor, bold = false, rojo = false }) => {
    doc.setFont('Helvetica', bold ? 'bold' : 'normal');
    doc.setFontSize(8.8);
    doc.setTextColor(rojo ? 180 : 40, rojo ? 0 : 40, rojo ? 0 : 40);
    doc.text(`${label}:`, resX, y);
    doc.text(`Q${parseFloat(valor || 0).toFixed(2)}`, resX + resW, y, { align: 'right' });
    doc.setTextColor(40, 40, 40);
    y += lineH;
  });

  doc.line(resX - 2, y - 3, resX + resW + 2, y - 3);

  if (anulada) {
    doc.setFont('Helvetica', 'bold');
    doc.setFontSize(38);
    doc.setTextColor(200, 30, 30);
    doc.text('ANULADA', pW / 2, 150, { align: 'center', angle: -20 });
    doc.setTextColor(40, 40, 40);
  }

  // Pie
  doc.setFont('Helvetica', 'italic');
  doc.setFontSize(7);
  doc.setTextColor(100, 100, 100);
  doc.text(notaPie, 10, pH - 10);
  doc.setTextColor(40, 40, 40);
  doc.setFillColor(...COLOR_ORO);
  doc.rect(0, pH - 5, pW, 5, 'F');
};
